mapper.select:
    	SELECT COUNT(1)
    	FROM REP_REVEAL
    	WHERE 1=1

			AND REP_ID = #{tabNum,jdbcType=VARCHAR}


			AND REPORT_NAME = #{reportName,jdbcType=VARCHAR}


			AND PRODID = #{PROD_ID,jdbcType=VARCHAR}


			AND START_DATE = STR_TO_DATE(#{START_DATE,jdbcType=VARCHAR},'%Y-%m-%d')


			AND END_DATE = STR_TO_DATE(#{END_DATE,jdbcType=VARCHAR},'%Y-%m-%d')

		AND STATUS='E'
		AND CONFIRM_STATUS='1'

        SELECT 
			count(1) 
		FROM 
			REP_REVEAL
		WHERE
			REP_ID = #{tabNum,jdbcType=VARCHAR}
		AND IF(!ISNULL(PRODID) , PRODID , '0' ) = #{PROD_ID,jdbcType=VARCHAR}
		AND IF(! ISNULL(DATE_FORMAT(START_DATE,'%Y-%m-%d')) , DATE_FORMAT(START_DATE,'%Y-%m-%d') ,'0') = #{START_DATE,jdbcType=VARCHAR}
		AND IF(! ISNULL(DATE_FORMAT(END_DATE,'%Y-%m-%d')) , DATE_FORMAT(END_DATE,'%Y-%m-%d') ,'0' ) = #{END_DATE,jdbcType=VARCHAR}
		AND STATUS='E'
